    const grpAns = (k, n, desc) => '<span class="ts-ans ts-ansg"><span class="ts-kic ts-aic">' + ANSICON[k] + '</span><span>' + n + '<span class="cs-grpdesc">' + desc + '</span></span></span>';
    const ans = (k, n) => '<span class="ts-ans"><span class="ts-kic ts-aic">' + ANSICON[k] + '</span><b>' + n + '</b></span>';
    const BIZ = ['tg-seq-business', 'The business comes first', '<p>Who the business serves, what it wants, and how customers find it decide everything after. Jimdo’s onboarding asks three questions; only one answer reaches Companion today. Each points to a kind of site:</p>'
      + gtab(['Answer', 'The site it calls for', 'How the look leans'], [
        [grpAns('g_goal', 'The goal', 'What brings them to Jimdo'), '', [
          [ans('launch', 'Launch a new business'), 'Nobody knows them yet, so the home page works like a landing page: one offer, one next step', 'Clear and calm, nothing that competes with the offer'],
          [ans('grow', 'Grow my business'), 'More services, each with a page to compare', 'Tighter spacing, quieter headings'],
          [ans('personal', 'Build a personal site'), 'A portfolio: the work leads, with few words', 'Bigger headings, more room, quieter text']]],
        [grpAns('g_help', 'What would help', 'Up to three'), '', [
          [ans('online', 'Get my business online'), 'A first site: the home page, the offer, and how to reach them', 'The middle mix, until the content says more'],
          [ans('promote', 'Start promoting my business'), 'A page per service, named the way people search', 'Text that holds up for visitors who arrive cold'],
          [ans('bookings', 'Get my first bookings'), 'Short booking pages, the next step always in reach', 'Few words, large targets'],
          [ans('sell', 'Sell products online'), 'Collection and product pages', 'Tighter, with prices easy to scan']]],
        [grpAns('g_find', 'How customers find you', 'All that apply'), '', [
          [ans('referrals', 'Word of mouth and referrals'), 'Trust and practical details up front: who, credentials, and hours', 'Calm and easy to read'],
          [ans('social', 'Social media'), 'A short home page, photos first, booking one tap away', 'Text steps back: smaller text, more room'],
          [ans('search', 'Search engines'), 'Pages named by what people search, with clear headings', 'Clear headings, easy reading'],
          [ans('walkins', 'Walk-ins and foot traffic'), 'Opening hours and the address on the home page', 'Tighter, with details easy to spot'],
          [ans('events', 'Events and networking'), 'Like a referral: people check who they met', 'Calm and easy to read'],
          [ans('market', 'Online marketplaces'), 'Visitors compare, so services and prices are stated plainly', 'Tighter, with prices easy to scan']]]])
      + '<p>A proposal. The answers set the starting point, and ' + docLink('optimize|tg-themetype', 'the site’s content corrects it') + '. They also shape headings and kickers: ' + docLink('headings|tg-companion-start', 'Where Companion could start →') + '</p>'];
    const STRUCT = ['tg-seq-structure', 'Structure follows purpose', '<p>The business decides which pages a site needs, and in what order. A designer asks what visitors come for, then gives each answer its place:</p><ul>'
      + '<li><b>The page people land on carries the most weight.</b> For referrals that’s the home page. For search, it’s often a service page.</li>'
      + '<li><b>Each page does one job.</b> One explains, one compares, one takes bookings. A page doing two jobs serves neither well.</li>'
      + '<li><b>What visitors look for first comes first.</b> Hours and the address for walk-ins, the offer for cold visitors, proof for referrals.</li></ul>'
      + '<p>Each page’s job then decides how people read it. ' + docLink('headings|tg-intent', 'What each page is for →') + '</p><p>Together, a site’s pages decide its look:</p><ul>'
      + '<li><b>Mostly pages people read</b> lean toward bigger body text.</li>'
      + '<li><b>Mostly pages people compare</b> lean toward tighter spacing.</li>'
      + '<li><b>A site led by a few statements</b> leans toward bigger headings, with room around them.</li></ul>'];
    const CONTENT = ['tg-seq-content', 'Content follows each page’s job', '<p>Each page says what its job needs, for the way its visitors arrive:</p><ul>'
      + '<li><b>From a search,</b> it says at once what and where, with the term people searched in the heading.</li>'
      + '<li><b>From a referral,</b> it confirms who they are, their credentials, and how to book.</li>'
      + '<li><b>From social media,</b> it stays short and photo-led, with the next step one tap away.</li>'
      + '<li><b>In person,</b> it puts the opening hours and the address first.</li></ul>'
      + '<p>That content gives the look its facts: text per block, title length, and whether photos or words lead. Headings and kickers follow the same jobs: ' + docLink('headings|tg-kickers-pair', 'Heading and kicker, as a pair →') + '</p>'];
