    const XT = (who) => '<b>' + XS[who][0] + '</b> ' + xtags(who) + '<br><code class="cs-lchip">' + XS[who][1] + '</code>';
    const XL = (...ids) => ids.map(([id, t]) => docLink('optimize|' + id + '-ic', t)).join('<br>');
    const XS = {
      chat: ['Companion chat', 'BusinessAssistantDeep'], ctx: ['Business interview', 'BusinessContext'], onb: ['Onboarding', 'GrowthOnboarding'],
      txtgen: ['Profile texts', 'TextGeneration'], create: ['Website creation', 'WebsiteCreation'], edit: ['Website editing', 'WebsiteEditing'],
      text: ['Website texts', 'WebsiteText'], color: ['Color palettes', 'ColorPalette'], seo: ['SEO skill', 'seo'], brain: ['Proactive suggestions', 'GrowthBrain'],
      order: ['The order', 'site-order'] };
    // what each part is (Nov 12, Alberto: anyone should tell an expert from a skill): the chat is the agent, a skill is a page of
