    const XKIND = { chat: 'Agent', seo: 'Skill', order: 'Skill' }, XNEW = { order: 'New' }, KNEW = { 'edit-design': 'New tool' };
    const BADGE = (t, c) => '<span class="ts-cmpbadge ts-cmpbadge-' + c + '">' + t + '</span>';
