    const codeWords = (t) => esc(t).replace(/`([^`]+)`|(\$?\{[A-Za-z_][\w.]*\})|\b([a-z]+(?:_[a-z0-9]+)+|[a-z]+[A-Z]\w*|[\w-]+\.(?:ts|md|js)|[a-z]+\.[a-z][\w.]*)\b/g, (m, a, b, c) => '<code class="cs-lchip">' + (a || b || c) + '</code>');
