      + '<code class="cs-fxsig">' + (o.lang === 'css' ? hlCss : hl)(o.sig) + '</code><dl class="cs-fxmeta"><dt>Used for</dt><dd>' + chips(o.use) + '</dd>' + (o.deps ? '<dt>Depends on</dt><dd>' + chips(o.deps) + '</dd>' : '') + '</dl>'
      + '<div class="cs-fxlab">Rule</div><pre class="cs-fxrule">' + o.rule.split('\n').map(o.lang === 'css' ? hlCss : hl).join('\n') + '</pre>'
