  const RM = [{"id": "rm-1", "t": "December: the new path, dark", "who": "Staff and test sites", "when": "Built in weeks 9 and 10, shipped dark in week 11", "track": "Core", "size": "Large", "problem": "Today every size and gap is a number typed into a rule. The renderer’s stylesheet sets the headings, and the theme styles override them with !important rules. Rewriting that in place for every site is risky, and no flag could undo it.", "goal": "The new type runs end to end on real infrastructure, and no customer sees it.", "ships": ["A second, new path: the new tokens for the core blocks, scoped under an attribute on the page’s root. Today’s CSS stays untouched.", "A type version stored with each site: 1 today, 2 for the new type. Today’s Font size stays as it is, so the way back is a version flip.", "One rollout flag, kept apart from the stored version, as a kill switch.", "A re-render and cache purge for the sites that switch, and a rollback drill.", "Screenshot tests on the scan’s sample, at 360px, 800px, and 1280px. If the tooling is new, they can follow in week 11 without holding up the release."], "nots": "Any change for customers.", "eng": ["The token writer, from SPEC.md and the [[formulas||Formulas]]: one pure function from settings to tokens.", "The core blocks read tokens under the version 2 attribute. Every other block keeps today’s rules.", "Under version 2, the theme styles stop writing !important sizes.", "A rollback drill: a test site switched to version 2 and back, through the cache."], "design": ["Review the screenshot differences on test sites."], "decide": [["The stored data model and the flag", "Engineering, at the team refinement", "Week 8"], ["How the site’s styles win: cascade layers or the root attribute", "Engineering, at the team refinement", "Week 8"], ["Where the published CSS is made: on the server, in a build step, or in the renderer. Design’s view: static sites", "Engineering, at the team refinement", "Week 8"], ["How big the build is, from the spike, and go or no-go", "Engineering", "Week 8"]], "depends": "The team refinement and the spike in week 8, and color application shipped.", "measure": [["Test sites back to today’s page with version 2 off", "Not tested", "Every one"], ["The rollback drill, through the cache", "Not run", "Passes"]], "rollout": "Dark: version 2 runs only on staff and test sites, so it ships as soon as the build is done. Rolling back is the version flip.", "done": ["Turning version 2 off gives back today’s page.", "The rollback drill passes.", "Every core block renders version 2 on test sites."], "risks": [["Specificity fights with the renderer’s !important rules and hashed class names.", "Under version 2 the theme styles stop writing them."], ["A flag flip only reaches a site after a re-render (an assumption to confirm at the refinement).", "The re-render, and the rollback drill."], ["Two weeks is tight for tokens, the stored version, the re-render, and screenshot tests.", "The spike sizes the build, and the screenshot tests can follow in week 11."]], "proto": "[[scale|cmp-type|Type scale: today’s text styles next to the new ones]], [[space|cmp-space|Spacing: today’s gaps]], and the [[css||CSS tab]]."}, {"id": "rm-2", "t": "January: new type for new sites", "who": "Every new site", "when": "Ready in December, released in the first week of January", "track": "Core", "size": "Large", "problem": "Today’s scale has four fixed sizes: Heading 3 to 6 are all 18px, everything jumps at 1281px, and every heading has a line height of 1.3. Font size changes the text but not the space between text elements.", "goal": "Every new site starts with type that looks designed at every width.", "ships": ["The fluid type scale: eleven styles on one modular scale, from Mobile at 360px to Desktop at 1280px. New sites start at Headings Balanced.", "Typography spacing that follows Font size: heading to text, paragraphs, text to buttons, and inside cards. [[space|tg-space|How space works]] draws the line: gaps inside a group are typography, gaps between groups are block spacing.", "Heading line heights from each font’s own measurements, and one line height per text style, as listed on the [[scale||Type scale]] tab, with 1.5 for body text and buttons.", "The type corrections, as one core part (Alberto, Nov 4): text balancing, ligatures, even figures in headings, optical sizing, hanging punctuation, tighter big headings, and the [[corrections|tg-a11y|accessibility rules]].", "Lines of about 65 characters, and the [[scale|tg-floors|floors]].", "Font size: Small, Medium, and Large on the new scale. Today’s four options become three: existing sites move in release 3.", "Headings: Subtle, Balanced, and Strong. It ships apart from block spacing: until block spacing ships, it moves the headings and small text only, not the space between blocks. Open (Nov 10): a smaller first release, [[optimize|tg-fontonly|Font size only]], ships Font size alone, keeps every site on Headings Balanced, and adds Headings later.", "The new Appearance panel, with the themes and its organization (TRF-4178), Sizing (Font size and Headings), and Optimize, which suggests sizes for the site, says why, and keeps Undo.", "The new defaults in website creation, AI website creation, and the fallback."], "nots": "Font loading, block spacing, and suggestions: they’re follow-up projects. Existing sites: release 3.", "eng": ["Engineering’s audit of the core blocks: which text and gaps each one has. Design maps them to styles from there, and reviews the result.", "Typography spacing in the core blocks, then in the non-core blocks and navigation with the teams that own them (bookings, smart forms, store, and loops), against a token contract.", "Fallbacks for newer CSS: without text-wrap or text-box trim, text looks as it does today.", "Blank lines handled in CSS under version 2, as decided at the refinement.", "The published page’s lang, so long German words hyphenate. The prototype’s word-fitting script doesn’t ship.", "Each body font’s 500 weight, for Medium buttons. Today a site loads only its font pair’s weights, and the browser fakes any weight that’s missing."], "design": ["Map each block’s text and gaps to styles, from engineering’s audit.", "Three heading sizes to pick, like today (decided Nov 5): Large, Medium, and Small heading (Heading 2 to 4). The cover’s Heading 1 and Heading 5, for titles inside components, are set by the block.", "Review every core block at Mobile, Tablet, and Desktop."], "decide": [["How blank lines behave under version 2", "Product and design, at the team refinement", "Week 8"], ["Can new sites ship while bookings, forms, store, and loops keep today’s values?", "Product", "Week 7, the Q1 plan"], ["Heading styles in the editor", "Product and design", "Week 8"]], "depends": "Release 1, and the other teams’ time for their blocks.", "measure": [["Publishing on new sites, as a guardrail", "From December", "No drop"], ["Text that overflows, from 320px to 1440px", "To check", "None"], ["Support tickets about type", "From December", "Flat"]], "rollout": "New sites only, through the flag.", "done": ["No text overflows on new sites at any width.", "A design review signs off every core block."], "risks": [["Bigger headings break layouts made for 36px titles.", "Hyphenation with the right lang, and a check of every block at 320px."], ["Pages mixing new core blocks with other teams’ blocks on today’s values.", "Product decides in the Q1 plan whether to wait."]], "proto": "The [[sheet||Specimen]], the [[scale||Type scale]], and [[corrections|tg-leading|line height from the font]]."}, {"id": "rm-3", "t": "Early Q1: new type for existing sites", "who": "Every existing site", "when": "Opt-in from late January, on by default in waves in February, every site by the end of February: early Q1. It needs the switch flow built in December", "track": "Core", "size": "Medium", "problem": "With color application, owners pick a style for each block. The new type changes every page at once: headings on Desktop grow by 8% to 22%, and on Mobile the biggest get about a fifth smaller. Owners shouldn’t open their site to a surprise.", "goal": "Every customer gets the new type, and nobody is surprised by it.", "ships": ["A switch in Appearance: the site old and new side by side, then one switch. It’s free, not an upgrade to a paid plan.", "A way back: the version flip, since today’s Font size is kept.", "Each site keeps its look (decided Nov 4): it moves to the Font size closest to its text today. Today’s S and M become Small, L becomes Medium, and XL becomes Large. See [[scale|tg-today|Moving existing sites, and a better default]].", "Existing headings matched by role, not by tag: the cover title becomes Heading 1, Heading 1 becomes Heading 2, Heading 2 becomes Heading 3, and Heading 3 to 6 become Heading 5. By tag, Heading 1 would jump from 48px to 76px.", "Sizes people set inline in the text editor, mapped to the nearest style.", "In February, the new type on by default in waves, starting with 5% of sites, with a notice and the same way back."], "nots": "Block spacing. A switch with no way back.", "eng": ["Let owners switch their site’s type version.", "The preview: render the site with both versions.", "The waves, through the re-render, paused when switch-backs pass the gate."], "design": ["The switch flow, the notice, and the way back.", "The help article and the support briefing."], "decide": [["Existing headings by role or by tag (the proposal: by role)", "Product and design", "Week 8"], ["Existing covers and hand-styled text, which mix headings and body text in one element: split covers on the switch and the rest when edited (the proposal), split everything, or leave them. Options on the Edit text page in Components", "Product, design, and engineering", "Week 8"], ["Do L and XL sites accept text 1px to 2px smaller on Mobile? Check how many sites use XL", "Product and design, with usage numbers per Font size", "Week 8"], ["How inline sizes from the text editor map to styles", "Design and engineering", "Week 8"], ["When the way back closes", "Product", "February"]], "depends": "Releases 1 and 2.", "measure": [["Owners who switch back", "None yet", "Under 10%, the gate for each wave"], ["Support tickets about the change", "From December", "Flat"]], "rollout": "Opt-in first, then waves from 5%. A wave pauses when the gate fails.", "done": ["Every site is on the new type, or its owner switched back."], "risks": [["Pages change a lot.", "The preview, the notice, and the way back."], ["Owners who opt in aren’t like everyone else.", "The first wave of 5% shows how everyone else reacts."], ["Empty paragraphs people used for space add extra room once text carries its own spacing.", "Decided at the refinement, handled in CSS, and checked on the scan’s sample before the first wave."]], "proto": "New, Old, and Side by side above the [[sheet||Specimen]] and the [[specimen||Examples]], and the CMS view’s New and Old."}], RM_F = [{"id": "rm-f1", "t": "Font loading", "who": "Every site and its visitors", "start": "Late Q1, in March, once the font data is ready. Matched fallback fonts can even ship earlier, on today’s path, behind their own switch.", "goal": "Steadier pages while fonts load.", "ships": ["Matched fallback fonts: in the prototype, text moved 76% less while fonts loaded."], "why": "It doesn’t change the scale, and it needs fallback metrics for every font in the catalog, which shouldn’t hold up the core. The type corrections ship in January.", "cost": "Pages keep jumping while fonts load, as they do today.", "decide": [["Who owns the font data process", "Engineering", "Q1 planning"]], "proto": "Type corrections’ [[corrections|tg-loading|Later: font loading]] section."}, {"id": "rm-f2", "t": "Block spacing", "who": "New sites first, then existing ones", "start": "Q2, after the core, on its own. It touches every block, other teams’ blocks too, so it doesn’t fit Q1. If the blocks project happens, it can ride on it.", "goal": "Every block follows the same spacing rules, and owners can make a site roomier or tighter.", "ships": ["[[space|tg-width|Content up to 1440px wide]], and side padding that grows with the screen.", "The same padding above and below every block, and the gaps between groups.", "[[space|rule-1|Same background, one gap]].", "The Spacing control in Appearance."], "why": "It’s a separate track, its scope is still open, and it touches every block.", "cost": "Blocks keep their own padding, and people keep adding blank lines.", "decide": [["The spacing scope the kickoff left open", "Product", "Week 6"], ["On its own, or with the blocks project if it happens", "Product", "Q1 planning"]], "proto": "The [[space||Spacing]] tab, Show space on the [[specimen||Examples]], and [[space|tg-space|How space works]]."}, {"id": "rm-f3", "t": "Suggestions", "who": "Owners, and AI website creation", "start": "Late Q1, in March, after the usability test in week 7. Headings and Optimize ship in January.", "goal": "Each site gets the sizing that suits its business and content, from Optimize or from Companion.", "ships": ["[[optimize|tg-fit-rules|The rules table]], applied by Optimize in Appearance, with Block spacing once block spacing ships.", "A Companion skill that reads the site, moves the same controls, and says why."], "why": "Suggestions need the usability test’s answer on the controls, and Companion needs the site’s content read. The kickoff worried two controls are a lot to learn; the test checks it.", "cost": "Until then, Font size, Headings, and Optimize, from January.", "decide": [["Which sizing controls ship, with the test as one input", "Product and design", "Week 8, after the test"], ["In the editor or on a server", "Engineering", "Q1 planning"]], "proto": "The CMS view’s Controls variants and Optimize, and AI optimizations’ [[optimize|tg-suggest|How suggestions work]]."}, {"id": "rm-f4", "t": "Retire the old path", "who": "Nobody, by design", "start": "Q2 at the earliest, after release 3’s way back closes.", "goal": "One path, and smaller CSS.", "ships": ["Today’s size and gap rules removed, and the type version with them."], "why": "It can only happen once every site has moved and the way back has closed.", "cost": "Two paths to maintain for a while.", "decide": [["When the way back closes", "Product", "February"]], "proto": "[[scale|cmp-type|Type scale: today’s text styles next to the new ones]]."}];
  const RM_HEARD = [["Timing and capacity", [["After color application", "Typography starts after color application ships (Arezoo, Vishwajeet), and before color generation (the triad).", "The team refinement and the spike in week 8, right after color application, and the build in weeks 9 and 10. Color generation follows typography."], ["No separate spec", "The spec is tight next to the color work (Motaki).", "No separate spec phase. SPEC.md and the prototype go to the team refinement, and the decisions are made there."], ["What ships when", "Planning needs to know what ships this quarter.", "This quarter: the refinement, the spike, the core blocks on the new path, release 1 shipped dark, and new sites ready in December. January: release 2. Late January and February, early Q1: release 3, if the switch flow is built in December. March, late Q1: the follow-ups that fit."]]], ["Scope", [["Two kinds of spacing", "Split typography spacing, between text elements, from block spacing, at the edges of blocks (Motaki; Vishwajeet and Alberto agreed).", "Two tracks. The core is typography; block spacing is a follow-up project, with content width and side padding."], ["Together or apart", "Whether both happen at once is still open.", "It’s settled in the spacing alignment, week 6. The core works either way."], ["Font size leaves space alone", "Font size changes the text, not the space between elements. Block spacing is fixed, and every block does its own thing.", "Release 2 makes typography spacing follow Font size. Block spacing follows as its own project."], ["Blank lines for space", "Today the only way to add space is blank lines.", "They’re handled in CSS under version 2, decided at the refinement, so the way back keeps working."], ["No partial styling", "No styling for part of a text: no color or case for a few words (agreed).", "Out of scope."]]], ["Controls and themes", [["Too much to learn", "Font size and Scale are a lot to learn, and owners learn by trial and error. One slider came up instead.", "Trying things is how owners learn, and the controls aren’t complicated. Clear names and pictures carry it: Font size and Headings, each with faces that show what changes, ship in release 2, and the usability test shows where people still struggle."], ["Independent of themes", "Keep the system independent of themes: most sites have custom palettes, and themes change.", "Every site starts at the same defaults. Themes only feed suggestions, a follow-up."], ["A Companion skill", "Companion could apply what good looks like, with a skill.", "The expression and suggestions follow-up."]]], ["Existing sites and how we work", [["A way onto the new system", "Existing users need a way onto the new system, a kind of upgrade.", "Release 3: a free switch, opt-in first, then on by default in waves, with a way back."], ["Old and new on a real site", "Show a before and after on an ordinary customer site, not a template.", "From the site scan’s sample, before the refinement."], ["Design what owners see", "Design what users will see, not the controls.", "The CMS view shows the editor as owners see it. The Type view is internal."]]]], RM_PRE = [["From engineering, before the refinement:", "an audit of the core blocks: which text and gaps each one has. Design maps them to styles from there. Today’s Font size formulas came on Nov 4 (Motaki)."], ["The spacing alignment.", "Scope and priority of block spacing, the point the kickoff left open. Week 6, product."], ["The Q1 plan,", "in week 7, with the other teams booked."], ["A one-day site scan,", "before the refinement: Font size use, blank lines, and block usage. It picks the screenshot sample and an ordinary customer site to show old and new."], ["The refinement package,", "from design in weeks 6 and 7: the prototype, SPEC.md, and the decisions below, so one session is enough. Design execution is already done."], ["The team refinement,", "in week 8: the stored data model, the flag, the cascade, the cache, and blank lines, decided in one session."], ["The spike,", "in week 8, right after the refinement: one core block through the new path. Go or no-go for the build."], ["The usability test,", "in week 7, on the prototype, with three versions of the sizing controls: Raw controls, Font size only, and Read or show. It gives us pointers and shows how owners think about size. It doesn’t make the decision: what each costs to build, how existing sites move, and how each fits the system weigh in too."]], RM_RULES = [["Every customer, not only new ones.", "The goal is the new type on every site: new sites first, then existing sites through one switch with a way back. It’s free: not an upgrade to a paid plan."], ["The core first, the rest as follow-ups.", "Three releases get the new type to everyone. Font loading, block spacing, suggestions, and cleanup are projects of their own, each shippable later."], ["No extra cycles.", "One team refinement, a spike, and a two-week build, in the slot the triad gave typography: right after color application, before color generation."], ["A new path, never a rewrite of today’s.", "Today’s CSS stays untouched. Turning the new path off gives back today’s page."], ["Typography before block spacing.", "They’re separate tracks, as the kickoff agreed. [[space|tg-space|How space works]] draws the line between them."], ["The system stands on its own.", "Every site starts at the same defaults. Themes and Companion only suggest."]], RM_LATER = [["Styling part of a text,", "like a color or case for a few words. Out of scope, agreed at the kickoff."], ["Templates and per-theme values.", "Only the restaurant template exists, and the system doesn’t depend on themes."], ["Personality:", "boxed kickers, link styles, and button weight are experiments, to test with owners first."], ["Corners that grow", "with their text."], ["Body line height per font,", "deferred."], ["More heading sizes to pick:", "decided against: three, like today."], ["Spacing per block:", "the system says no, to keep every page’s rhythm."], ["Custom fonts,", "which need the font data process first."]], RM_REVIEW = [["kept", "Release 1 ships dark, as a new path.", "Today’s CSS stays untouched, and turning the new path off gives back today’s page."], ["kept", "One January release for new sites.", "And the fixes moved to a follow-up, so the release is smaller."], ["kept", "Owners’ choices apart from the rollout flag.", "A type version stored with each site, and today’s Font size kept."], ["kept", "Re-render and rollback.", "Inside release 1, with one rollback drill."], ["kept", "The spike as a gate.", "In week 8, right after the team refinement."], ["lighter", "A scan of published sites.", "One day, not two weeks."], ["kept", "Blank lines decided early, in CSS.", "At the team refinement."], ["lighter", "A slower default for existing sites.", "Waves from 5%, without a separate holdout group."], ["kept", "Content width and side padding move to block spacing.", "Block spacing is now a follow-up project."], ["dropped", "A separate decision memo and spec phase.", "The team refinement decides instead, so the core needs no extra cycles."]], RM_ALONG = [["A help article and a support briefing,", "before release 3. Font size has three options instead of four, and an existing site’s label changes while its text stays the same size."], ["Translations", "for the switch flow and the notice, with lead time."], ["Switch-backs and support tickets,", "watched for every wave. Fuller dashboards come with the follow-ups."], ["A light QA plan:", "the defaults and the biggest Font size, at 320px, 360px, 800px, and 1280px, on the scan’s sample, with German content."], ["A named design reviewer", "for the screenshot differences, once Alberto moves to the blocks project."]];
  const RM_KINDS = { done: 'Done', design: 'Design', evaluation: 'UX evaluation', build: 'Engineering', ship: 'Release', support: 'Support', later: 'Later', milestone: 'Milestone' };
