    for (let cy = 0; cy < 4; cy++) head += '<div class="ts-rmcyc" style="grid-column:' + (cy * 2 + 2) + ' / span 2">Cycle ' + (21 + cy) + '<small>' + rmDay(cy * 2 + 5, 0) + ' to ' + rmDay(cy * 2 + 6, 4) + '</small></div>';
    for (let w = 5; w <= 12; w++) head += '<div class="ts-rmwk" style="grid-column:' + (w - 3) + '">W' + w + '</div>';
    head += '<div class="ts-rmspan h ts-rmhol" style="grid-column:10">Holidays</div>' + ['January', 'February', 'March'].map((m, i) => '<div class="ts-rmspan" style="grid-column:' + (11 + i) + '">' + m + '<small>2027</small></div>').join('')
