    const legend = ['done', 'design', 'evaluation', 'build', 'ship', 'support', 'later', 'milestone'].map((k) => '<button type="button" class="ts-rmchip k-' + k + '" data-rm-filter="' + k + '" aria-pressed="' + (rmFilter === k) + '"><i></i>' + RM_KINDS[k] + '</button>').join('')
