    const tab = (head, rows) => '<table class="ts-au-tab"><thead><tr>' + head.map((x) => '<th>' + x + '</th>').join('') + '</tr></thead><tbody>' + rows.map((r) => '<tr>' + r.map((x) => '<td>' + x + '</td>').join('') + '</tr>').join('') + '</tbody></table>';
    const px = (n) => '<code class="cs-lchip">' + (n >= 999 ? 'pill' : n + 'px') + '</code>';
    // in em, a button or field corner is shown as its em value and the px it gives at the button's two sizes
    const bMin = T.style('button').min, bMax = T.style('button').max, r1 = (n) => Math.round(n * 10) / 10;
    const ctl = (n) => (n >= 999 ? px(n) : !T.cornerEm || !n ? px(n) : '<code class="cs-lchip">' + +(n / 16).toFixed(4) + 'em</code> ' + r1(n * bMin / 16) + 'px → ' + r1(n * bMax / 16) + 'px');
    const rows = (CS.palettes ? CS.palettes() : []).filter(([k]) => (window.ThemeSites || {})[k]).map(([k, pal]) => {
      const r = pal.radius || 0, btn = r >= 20 ? 999 : r, l = lookOf(T, k, r);
      return [pal.name, ctl(btn), ctl(Math.min(btn, 8)), px(l.card), l.img ? px(l.img) : '<code class="cs-lchip">0px</code> (square in the template)', r === 0 ? 'Square' : r >= 20 ? 'Pill, cards from the template' : 'Rounded, cards twice the button'];
    });
    return '<div class="cs-doc ts-guide ts-audit">' + pageHead('Corners and details from the theme', 'The details a theme brings: one corner system for buttons, cards, fields, and photos, and a personality of kicker, link, and button styles.', chapterKick('shapes'))
      + chipLegend()
      + sec('why', WHY_T, '<p>A theme only feels designed when its details agree, like rounded buttons on rounded cards. Each segment’s look depends on them as much as on color and type.</p>'
        + '<p>One corner value and a few personality choices give each theme its character, and nobody has to style elements one by one. </p>' + callout('key', 'One corner sets them all.', 'The theme’s button radius sets every other corner, so rounded buttons never sit on square cards.') + further([STORY_CARD()]))
      + sec('rules', 'Corner rules', tab(['Element', 'Corner', 'Why'], CORNER_RULES))
      // corners that grow with their text (Oct 30, experimental): the same radius in px or in em
      + sec('grow', 'Corners that grow with their text ' + EXPERIMENTAL, '<p>Buttons and fields grow with the type: their text and padding come from Font size. A corner in px stays the same while the button grows, so a big button looks less round than a small one. In em, the corner grows with the button’s own text, so every button keeps the same shape at every size.</p>'
        + '<p>Try it with <b>Corners</b> in the sidebar’s Personality section: Fixed or Grows. The buttons below follow it.</p>'
        + (() => { const r = Math.min(T.pair.radius || 0, 999), rad = (fs) => (r >= 20 ? 999 : T.cornerEm ? r * fs / 16 : r) + 'px';
          return '<div class="ts-cornerdemo">' + [[bMin, 'Mobile'], [bMax, 'Desktop']].map(([fs, at]) => '<figure><span style="font-size:' + r1(fs) + 'px;border-radius:' + rad(fs) + '">Book a session</span><figcaption>' + at + ', ' + r1(fs) + 'px text, corner ' + (r >= 20 ? 'pill' : r1(parseFloat(rad(fs))) + 'px') + '</figcaption></figure>').join('') + '</div>'; })()
        + '<p>At 16px text the two match exactly, so the values below are the Font size Medium, Headings Balanced, and Block spacing Regular reference. Pills stay pills. Cards and photos keep their px corners: they’re sized by the layout, not the type. Off by default while we try it.</p>')
